<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { Wrench, LayoutDashboard, MoveHorizontal, CircuitBoard, Activity, OctagonX, RotateCcw, Play, Square, Plug, Unplug, Settings2, X, Check, AlertTriangle, ArrowLeft, ArrowRight, Save, Crosshair, RefreshCw, Home, SlidersHorizontal, ChevronRight, Radio, ShieldCheck, Cpu, Cable, WifiOff } from 'lucide-vue-next'
import { hmi,ready,manual,start,run,scanPorts,notice,stopJog,startJog } from './store'
import OutputCard from './OutputCard.vue'
const page=ref('overview'), settings=ref(false), selected=ref(4), clock=ref('')
const conn=ref({mode:'serial',port:'',baud:115200,unit:1})
const speed=ref(1250),target=ref(0),relative=ref(false),drafts=ref([]),lim=ref({enable:false,min:-100000,max:100000})
const home=ref({fast:1250,backoff:300,slow:300,mode:0,direction:null}),wdt=ref(2000)
const labels=['A','B','C','D','E','F','G','H']
let localNames
try {localNames=JSON.parse(localStorage.getItem('2416-axis-names')||'[]')}catch{localNames=[]}
const names=ref(labels.map((x,i)=>localNames[i]||x+' 轴'))
const axisName=ref('')
const tabs=[{key:'overview',name:'总览',icon:LayoutDashboard},{key:'axes',name:'轴与点位',icon:MoveHorizontal},{key:'home',name:'回原与限位',icon:Home},{key:'io',name:'I/O',icon:CircuitBoard},{key:'diagnostics',name:'诊断',icon:Activity}]
const title=computed(()=>tabs.find(x=>x.key===page.value)?.name)
const axis=computed(()=>hmi.state.axes[selected.value]||{position:0,state:0,homed:false,speed:0,target:0})
const cfg=computed(()=>hmi.state.config.axes?.[selected.value]||{})
const idle=computed(()=>manual.value && !!hmi.state.axes[selected.value] && axis.value.state===0)
const homed=computed(()=>hmi.state.axes.filter(x=>x.homed).length)
const moving=computed(()=>hmi.state.axes.filter(x=>x.state!==0).length)
const bound=computed(()=>hmi.state.config.axes?.filter(x=>x.home!=null).length||0)
const stateText=s=>['空闲','点动中','定位中','回原中'][s]||'未知'
const number=n=>Number(n||0).toLocaleString('en-US')
const pin=n=>n==null?'未绑定':'X'+Number(n).toString(8)
const ypin=n=>n==null?'—':'Y'+Number(n).toString(8)
function syncAxis() {
  const data=hmi.state.points[selected.value]
  drafts.value=Array.from({length:8},(_,i)=>({name:data?.names[i]||'',position:data?.positions[i]||0,speed:data?.speeds[i]||1250}))
  lim.value={...(hmi.state.limits[selected.value]||{enable:false,min:-100000,max:100000})}
  axisName.value=names.value[selected.value]
}
watch(selected,()=>{stopJog();syncAxis()})
watch(()=>JSON.stringify(hmi.state.points),()=>syncAxis())
// Synchronize editable forms only when their device values actually change.
watch(()=>JSON.stringify(hmi.state.config.system||{}),()=>{
  const s=hmi.state.config.system
  if(s){home.value={fast:s.home_fast,backoff:s.home_backoff_hz,slow:s.home_slow,mode:s.home_mode,direction:s.home_direction??null};wdt.value=s.comm_wdt_ms}
})
watch(()=>hmi.state.connected,value=>{if(value){selected.value=Math.min(selected.value,Math.max(0,hmi.state.axes.length-1));syncAxis()}else stopJog()})
function navigate(key){stopJog();page.value=key}
async function connect(){stopJog();if(await run('connect',conn.value))settings.value=false}
async function mode(){stopJog();await run('mode',{value:manual.value?0:1})}
async function flash(){stopJog();await run('flash')}
async function writePoint(index,teach=false){const p=drafts.value[index];await run('point_write',{axis:selected.value,index,...p,teach})}
function rename(){const name=axisName.value.trim().slice(0,20)||labels[selected.value]+' 轴';names.value[selected.value]=name;localStorage.setItem('2416-axis-names',JSON.stringify(names.value));notice('轴名称已保存到本机')}
async function openSettings(){settings.value=true;await scanPorts();if(!conn.value.port&&hmi.ports.length)conn.value.port=hmi.ports[0].port}
let timer
onMounted(()=>{start();timer=setInterval(()=>clock.value=new Date().toLocaleTimeString('zh-CN',{hour12:false}),1000);syncAxis();window.studio={hmi,run,navigate,select:i=>selected.value=i}})
onUnmounted(()=>{clearInterval(timer);stopJog()})
</script>

<template>
  <div class="app-shell">
    <header class="topbar">
      <a class="brand" href="#" @click.prevent="navigate('overview')"><Wrench :size="25"/><span>李佳树的创意工坊<small>2416 Studio · STM32 设备控制台</small></span></a>
      <div class="system-controls">
        <button class="button" :class="{active:manual}" :disabled="!ready||hmi.pending.mode" @click="mode"><SlidersHorizontal :size="17"/>{{manual?'调试模式':'正常运行'}}</button>
        <button class="button" :disabled="!ready||hmi.pending.refresh" @click="run('refresh')"><RefreshCw :size="17" :class="{spin:hmi.pending.refresh}"/>读取设备</button>
        <button class="estop" :disabled="!ready" @click="stopJog();run('estop')"><OctagonX :size="18"/>全部急停</button>
      </div>
      <div class="top-status"><span class="badge" :class="ready?'badge-ok':'badge-warn'"><i class="status-dot"/>{{ready?'已连接':'未连接'}}</span><span class="mono clock">{{clock}}</span><button class="button" aria-label="连接设置" @click="openSettings"><Settings2 :size="19"/></button></div>
      <nav aria-label="主导航"><a v-for="tab in tabs" :key="tab.key" href="#" :class="{active:page===tab.key}" @click.prevent="navigate(tab.key)"><component :is="tab.icon" :size="18"/><span>{{tab.name}}</span></a></nav>
    </header>
    <div class="session-bar">
      <span class="connection-label"><i class="status-dot" :class="{pulse:ready}"/>{{ready?'状态流在线':'状态流离线'}}<span>/</span>{{title}}</span>
      <div class="session-summary"><span class="badge" :class="moving?'badge-warn':''">{{moving?moving+' 轴运动中':ready?'设备空闲':'等待连接'}}<span v-if="ready"> · {{manual?'调试':'正常'}}</span></span><span v-if="ready&&bound<hmi.state.axes.length" class="badge badge-warn">{{hmi.state.axes.length-bound}} 轴未绑定原点</span></div>
      <div class="inline"><span v-if="hmi.state.mode==='mock'" class="badge badge-warn">SIM · 模拟设备</span><span class="muted small mono">{{ready?(hmi.state.mode==='serial'?'MODBUS RTU · '+hmi.state.endpoint:'模拟连接'):'OFFLINE'}}</span><span class="mono small">V3.0</span></div>
    </div>
    <main class="content-area">
      <div class="page">
        <div class="page-heading"><div><p class="eyebrow">{{page==='overview'?'设备状态与快捷操作':page==='axes'?'手动调试与位置示教':page==='home'?'原点参考与行程配置':page==='io'?'现场输入与输出状态':'状态与追溯'}}</p><h1>{{title}}</h1></div><div class="inline"><span class="muted small">{{ready?'固件 '+hmi.state.version:'STM32F407 · 2416 控制板'}}</span><button v-if="ready" class="button" @click="openSettings"><Cable :size="16"/>连接设置</button></div></div>

        <template v-if="page==='overview'">
          <div class="summary-grid">
            <div class="summary-item"><span>设备连接</span><Cable/><strong>{{ready?hmi.state.endpoint:'未连接'}}</strong><small>{{ready?'固件握手通过 · 0x2416':'串口 RTU / 模拟设备'}}</small></div>
            <div class="summary-item"><span>已注册轴</span><Cpu/><strong>{{ready?hmi.state.axes.length:'—'}} <span class="muted">/ 8</span></strong><small>4 路硬件 PWM + 4 路软件脉冲</small></div>
            <div class="summary-item"><span>已完成回原</span><Home/><strong>{{ready?homed:'—'}} <span class="muted">/ {{ready?hmi.state.axes.length:8}}</span></strong><small>以设备回原完成标志为准</small></div>
            <div class="summary-item"><span>通信状态</span><Radio/><strong>{{ready?'在线':'离线'}}</strong><small>{{ready?'周期采样 150 ms · 心跳 250 ms':'打开连接设置以连接控制板'}}</small></div>
          </div>
          <div v-if="!ready" class="welcome-panel"><div class="welcome-symbol"><CircuitBoard :size="36"/></div><div><p class="eyebrow">2416 STUDIO / WORKSPACE</p><h2>从连接设备开始</h2><p class="muted">集中查看八轴状态、调试运动与管理示教点。也可以连接模拟设备，先体验完整操作界面。</p></div><button class="button primary" @click="openSettings"><Plug :size="17"/>连接设备</button></div>
          <section class="section-block"><header class="section-heading"><h2>轴状态 <span class="small muted">实时位置 / 回原状态</span></h2><a class="text-link" href="#" @click.prevent="navigate('axes')">轴与点位<ChevronRight :size="16"/></a></header>
            <div class="axis-grid"><button v-for="(_,i) in labels" :key="i" class="axis-card axis-overview" @click="selected=i;navigate('axes')"><div class="section-heading"><span class="object-name"><span class="axis-letter">{{labels[i]}}</span>{{names[i]}}</span><span class="badge" :class="hmi.state.axes[i]?.state?'badge-warn':''">{{ready&&hmi.state.axes[i]?stateText(hmi.state.axes[i].state):'离线'}}</span></div><div class="position-value">{{ready&&hmi.state.axes[i]?number(hmi.state.axes[i].position):'—'}}<span>pulse</span></div><div class="section-heading"><span class="muted small">{{i<4?'硬件 PWM':'软件脉冲'}}</span><span class="badge" :class="hmi.state.axes[i]?.homed?'badge-ok':''">{{hmi.state.axes[i]?.homed?'已回原':'未回原'}}</span></div></button></div>
          </section>
          <section class="section-block"><header class="section-heading"><h2>调试准备</h2></header><div class="readiness"><div><ShieldCheck :size="20"/><strong>读取真实绑定</strong><p>原点和限位由固件模板维护，连接后显示设备读回值。</p></div><div><MoveHorizontal :size="20"/><strong>切换调试模式</strong><p>进入调试模式后，可点动、定位、回原和写入点位。</p></div><div><Save :size="20"/><strong>示教与保存</strong><p>点位先写入 RAM，全部轴空闲时可保存到设备 Flash。</p></div></div></section>
        </template>

        <template v-if="page==='axes'||page==='home'">
          <div class="axis-tabs"><button v-for="(_,i) in labels" :key="i" :class="{selected:selected===i}" @click="selected=i"><span class="axis-letter">{{labels[i]}}</span><strong>{{names[i]}}</strong><small>{{ready&&hmi.state.axes[i]?number(hmi.state.axes[i].position)+' pulse':'未连接'}}</small><i class="status-dot" :class="{'dot-green':hmi.state.axes[i]?.homed}"/></button></div>
          <div v-if="!ready" class="inline-notice"><WifiOff :size="18"/>设备未连接。可浏览页面布局，连接后读取设备状态。<button class="button" @click="openSettings">连接设置</button></div>
          <div v-else-if="!manual" class="inline-notice"><SlidersHorizontal :size="18"/>当前为正常运行模式，运动调试和参数写入需要切换到调试模式。<button class="button" @click="mode">切换调试模式</button></div>
          <div class="axis-readout studio-readout"><div><div class="inline"><h2>{{names[selected]}}</h2><span class="badge" :class="axis.state?'badge-warn':''">{{ready?stateText(axis.state):'离线'}}</span><span class="badge" :class="axis.homed?'badge-ok':''">{{axis.homed?'已回原':'未回原'}}</span></div><div class="position-value">{{ready?number(axis.position):'—'}}<span>pulse</span></div></div><div class="readout-secondary"><div><span class="muted small">目标位置</span><strong class="mono">{{ready?number(axis.target):'—'}} <small>pulse</small></strong></div><div><span class="muted small">设定速度</span><strong class="mono">{{ready?number(axis.speed):'—'}} <small>Hz</small></strong></div><div><span class="muted small">脉冲方式</span><strong>{{selected<4?'硬件 PWM':'软件脉冲'}}</strong></div></div><div class="action-row"><button class="button" :disabled="!idle||cfg.home==null||hmi.pending.home" :title="cfg.home==null?'固件未绑定原点传感器':'启动单轴回原'" @click="stopJog();run('home',{axis:selected})"><Home :size="16"/>{{axis.state===3?'回原中':'回原'}}</button><button class="button" :disabled="!idle" @click="run('zero',{axis:selected})"><RotateCcw :size="16"/>当前位置清零</button><button class="button" :disabled="!ready" @click="stopJog();run('stop',{axis:selected})"><Square :size="16"/>停止本轴</button></div></div>

          <template v-if="page==='axes'">
            <section class="motion-layout section-block"><div class="jog-area"><header class="section-heading"><h2>点动</h2><span class="muted small">按住运行 · 松开停止</span></header><div class="jog-buttons"><button class="button jog-button" :class="{pressed:hmi.jog?.direction===-1}" :disabled="!manual||(!idle&&!hmi.jog)" @pointerdown="startJog($event,selected,-1,speed)" @pointerup="stopJog" @pointercancel="stopJog" @lostpointercapture="stopJog" @contextmenu.prevent><ArrowLeft :size="24"/>负向</button><button class="button jog-button" :class="{pressed:hmi.jog?.direction===1}" :disabled="!manual||(!idle&&!hmi.jog)" @pointerdown="startJog($event,selected,1,speed)" @pointerup="stopJog" @pointercancel="stopJog" @lostpointercapture="stopJog" @contextmenu.prevent><ArrowRight :size="24"/>正向</button></div></div><form class="move-area" @submit.prevent="run(relative?'move_rel':'move_abs',{axis:selected,target,speed})"><header class="section-heading"><h2>定位</h2><div class="segmented compact"><button type="button" :class="{selected:!relative}" @click="relative=false">绝对</button><button type="button" :class="{selected:relative}" @click="relative=true">相对</button></div></header><div class="move-inputs"><label>{{relative?'相对距离':'目标位置'}}<div class="input-unit"><input v-model="target" type="number" step="1" min="-2147483648" max="2147483647" required aria-label="目标位置"/><span>pulse</span></div></label><label>速度<div class="input-unit"><input v-model="speed" type="number" min="100" max="100000" step="1" required aria-label="运动速度"/><span>Hz</span></div></label><button class="button primary" type="submit" :disabled="!idle||hmi.pending.move_abs||hmi.pending.move_rel"><Play :size="16"/>执行</button><button class="button" type="button" :disabled="!idle" @click="run('resume',{axis:selected})">剩余步数恢复</button></div></form></section>
            <section class="section-block"><header class="section-heading"><h2>定位点表 <span class="small muted">8 个点位 · 坐标 / 名称 / 独立运行速度</span></h2><button class="button" :disabled="!manual||hmi.pending.flash||moving>0" @click="flash"><Save :size="16"/>{{hmi.pending.flash?'正在保存…':'保存到 Flash'}}</button></header><div class="table-scroll"><table class="points-table"><thead><tr><th>点位 / 名称</th><th>位置 (pulse)</th><th>速度 (Hz)</th><th>操作</th></tr></thead><tbody><tr v-for="(p,i) in drafts" :key="selected+'-'+i"><td><strong class="mono">P{{i}}</strong><input class="point-name" :aria-label="'P'+i+' 名称'" v-model="p.name" maxlength="11" :placeholder="'点位 '+i"/></td><td><input class="table-number" v-model="p.position" type="number" step="1" :aria-label="'P'+i+' 位置'"/></td><td><input class="table-number" v-model="p.speed" type="number" min="100" max="100000" step="1" :aria-label="'P'+i+' 速度'"/></td><td><div class="action-row nowrap"><button class="button" :disabled="!idle||hmi.pending.point_write" @click="writePoint(i,true)"><Crosshair :size="15"/>示教</button><button class="button" :disabled="!idle||hmi.pending.point_write" @click="writePoint(i)"><Save :size="15"/>写入</button><button class="button" :disabled="!idle||hmi.pending.point_run" @click="run('point_run',{axis:selected,index:i})"><Play :size="15"/>执行</button></div></td></tr></tbody></table></div><p class="table-hint">示教读取当前脉冲位置；写入后读回设备数据。点位名称、坐标和速度可保存到 Flash。</p></section>
            <section class="section-block local-name"><header class="section-heading"><h2>轴名称 <span class="small muted">仅保存在本机</span></h2></header><div class="inline"><input v-model="axisName" aria-label="轴名称" maxlength="20"/><button class="button" @click="rename">保存名称</button></div></section>
          </template>

          <template v-if="page==='home'">
            <section class="section-block"><header class="section-heading"><h2>原点与限位绑定 <span class="small muted">固件模板 · 只读</span></h2><span v-if="hmi.state.mode==='mock'" class="badge badge-warn">模拟绑定示例</span></header><div class="binding-grid"><div><small>原点输入</small><strong>{{ready?pin(cfg.home):'—'}}</strong><span class="badge" :class="cfg.home!=null&&hmi.state.di[cfg.home]?'badge-ok':''">{{cfg.home==null?'未配置':hmi.state.di[cfg.home]?'已触发':'未触发'}}</span></div><div><small>正向限位</small><strong>{{ready?pin(cfg.limp):'—'}}</strong><span class="muted small">仅服务回原搜索</span></div><div><small>负向限位</small><strong>{{ready?pin(cfg.limn):'—'}}</strong><span class="muted small">仅服务回原搜索</span></div><div><small>回原方向 / 方向输出</small><strong>{{hmi.state.config.system?.home_direction==null?(cfg.home_dir?'正向（模板）':'负向（模板）'):(hmi.state.config.system.home_direction?'正向（全局）':'负向（全局）')}} / {{ready?ypin(cfg.dir):'—'}}</strong><span class="muted small">{{cfg.inv?'方向反转':'方向未反转'}}</span></div></div><div v-if="ready&&cfg.home==null" class="inline-notice warn"><AlertTriangle :size="19"/>当前轴未绑定原点传感器，无法启动回原。需要在固件 axis_manager.c 中配置并重新烧录。</div></section>
            <section class="section-block home-layout"><div class="home-flow"><header class="section-heading"><h2>回原流程</h2><span class="badge">{{home.mode==1?'释放沿置零':'精确模式'}}</span></header><ol><li><span>01</span><div><strong>快速寻找原点</strong><small>按固件方向搜索；先碰限位则反向搜索。</small></div></li><li><span>02</span><div><strong>反向退到释放沿</strong><small>原点传感器释放后，按模式进入下一阶段。</small></div></li><li v-if="home.mode==0"><span>03</span><div><strong>慢速再次触发</strong><small>以慢速触发沿确定机械零点。</small></div></li><li><span>{{home.mode==1?'03':'04'}}</span><div><strong>停止并置零</strong><small>读取设备已回原标志；整个过程超时 30 秒。</small></div></li></ol></div><form class="parameter-panel" @submit.prevent="run('home_params',home)"><header class="section-heading"><h2>全局回原参数</h2><span class="muted small">所有调试轴共用</span></header><div class="form-grid"><label class="full-field">回原方向<select v-model="home.direction" aria-label="全局回原方向" :disabled="hmi.state.config.system?.home_direction==null"><option v-if="home.direction==null" :value="null" disabled>当前固件不支持，请更新固件</option><option :value="0">负向 · 向负方向搜索原点</option><option :value="1">正向 · 向正方向搜索原点</option></select><span class="muted small">写入后用于所有轴的上位机回原；固件自动掉电保持。</span></label><label class="full-field">回原模式<select v-model="home.mode"><option :value="0">精确模式 · 退回后慢找触发沿</option><option :value="1">快速模式 · 退到释放沿置零</option></select></label><label>快找频率 (Hz)<input v-model="home.fast" type="number" min="100" max="100000" required/></label><label>回退频率 (Hz)<input v-model="home.backoff" type="number" min="100" max="65535" required/></label><label>慢找频率 (Hz)<input v-model="home.slow" type="number" min="100" max="100000" required/></label><div class="parameter-note">快找 / 慢找 100–100,000 Hz<br/>回退 100–65,535 Hz</div></div><div class="modal-footer"><button class="button primary" :disabled="!manual||moving>0||hmi.pending.home_params"><Save :size="16"/>写入并读回</button></div></form></section>
            <section class="section-block"><header class="section-heading"><h2>软限位 <span class="small muted">运行行程保护 · 不参与回原</span></h2><span class="badge" :class="lim.enable?'badge-ok':''">{{lim.enable?'已启用':'已关闭'}}</span></header><form class="limit-form" @submit.prevent="run('limit',{axis:selected,...lim})"><label class="checkbox-field"><input type="checkbox" v-model="lim.enable"/>启用本轴软限位</label><label>负向边界 (pulse)<input v-model="lim.min" type="number" required/></label><label>正向边界 (pulse)<input v-model="lim.max" type="number" required/></label><button class="button" :disabled="!idle||hmi.pending.limit"><Save :size="16"/>写入并保存</button></form></section>
          </template>
        </template>

        <template v-if="page==='io'">
          <div v-if="!ready" class="inline-notice"><WifiOff :size="18"/>当前显示离线状态，连接后刷新输入输出。</div>
          <section class="section-block"><header class="section-heading"><h2>数字输入 <span class="small muted">24 路 · 消抖后状态</span></h2><span class="badge badge-ok">{{ready?hmi.state.di.filter(Boolean).length:0}} 路有效</span></header><div class="io-grid"><div v-for="(value,i) in hmi.state.di" :key="i" class="io-cell studio-io" :class="{on:ready&&value}"><span class="mono">X{{i.toString(8)}}</span><i class="status-dot"/><small>{{ready?(value?'ON':'OFF'):'—'}}</small></div></div></section>
          <section class="section-block"><header class="section-heading"><h2>数字输出 <span class="small muted">16 路 · 手动置 ON / OFF · 写入后读回</span></h2><span class="badge">轴脉冲 / 方向复用</span></header><div class="io-grid output-grid"><OutputCard v-for="(_,i) in hmi.state.do" :key="i" :index="i"/></div><p class="table-hint">调试模式下可直接置 ON / OFF。复用为轴脉冲或方向的 Y 点，仅在对应轴空闲时开放；轴运行时由固件独占。输出镜像不代表机械反馈。</p></section>
          <section class="section-block"><header class="section-heading"><h2>轴通道映射</h2></header><div class="table-scroll"><table><thead><tr><th>轴</th><th>输出方式</th><th>脉冲通道</th><th>方向输出</th><th>原点输入</th><th>正限位 / 负限位</th></tr></thead><tbody><tr v-for="(c,i) in (hmi.state.config.axes||[])" :key="i"><td>{{names[i]}}</td><td>{{c.pulse_mode?'软件脉冲':'硬件 PWM'}}</td><td class="mono">{{c.pulse_mode?'SOFT '+c.soft:'PWM '+c.pwm}}</td><td class="mono">{{ypin(c.dir)}}</td><td>{{pin(c.home)}}</td><td>{{pin(c.limp)}} / {{pin(c.limn)}}</td></tr><tr v-if="!ready"><td colspan="6" class="empty-state">连接后读取实际通道映射</td></tr></tbody></table></div></section>
        </template>

        <template v-if="page==='diagnostics'">
          <div class="summary-grid"><div class="summary-item"><span>设备版本</span><Cpu/><strong>{{ready?hmi.state.version:'—'}}</strong><small>2416 / STM32F407</small></div><div class="summary-item"><span>设备帧计数</span><Radio/><strong class="mono">{{ready?number(hmi.state.diag.frame_count):'—'}}</strong><small>当前通信端口</small></div><div class="summary-item"><span>设备错误帧</span><Activity/><strong class="mono">{{ready?number(hmi.state.diag.err_count):'—'}}</strong><small>{{hmi.state.error||'以设备诊断读回值为准'}}</small></div><div class="summary-item"><span>通信看门狗</span><ShieldCheck/><strong>{{ready?number(hmi.state.diag.wdt_ms)+' ms':'—'}}</strong><small>{{hmi.state.diag.wdt_triggered?'已触发':'未触发'}}</small></div></div>
          <section class="section-block"><header class="section-heading"><h2>通信看门狗</h2></header><form class="watchdog-form" @submit.prevent="run('watchdog',{value:wdt})"><label>超时时间 (ms)<input v-model="wdt" type="number" min="1000" max="60000" required/></label><button class="button" :disabled="!manual||hmi.pending.watchdog">写入并读回</button><p class="muted small">桌面程序每 250 ms 发送心跳，允许设置 1,000–60,000 ms。</p></form></section>
          <section class="section-block"><header class="section-heading"><h2>当前状态</h2><span class="badge" :class="hmi.state.error?'badge-danger':ready?'badge-ok':''">{{hmi.state.error?'通信异常':ready?'通信正常':'未连接设备'}}</span></header><div class="status-message"><Check v-if="ready&&!hmi.state.error" :size="20"/><AlertTriangle v-else :size="20"/><span>{{hmi.state.error|| (ready?'当前无通信异常。板卡未提供轴报警码，运动状态以各轴读回为准。':'设备未连接，请在连接设置中选择串口或模拟设备。')}}</span></div></section>
          <section class="section-block"><header class="section-heading"><h2>事件与命令历史 <span class="small muted">本次会话 · 最近 150 条</span></h2><button class="button" @click="hmi.history=[]">清空记录</button></header><div class="table-scroll history-table"><table><thead><tr><th>时间</th><th>结果</th><th>事件</th><th>说明</th></tr></thead><tbody><tr v-for="item in hmi.history" :key="item.id"><td class="mono">{{item.time}}</td><td><span class="badge" :class="item.good?'badge-ok':'badge-danger'">{{item.good?'已确认':'未完成'}}</span></td><td>{{item.message}}</td><td class="muted">{{item.detail||'—'}}</td></tr><tr v-if="!hmi.history.length"><td colspan="4" class="empty-state">暂无操作记录</td></tr></tbody></table></div></section>
        </template>
      </div>
    </main>
    <footer class="statusbar"><span>{{hmi.state.mode==='mock'?'模拟状态仅用于界面试用，不代表设备配置':'脉冲位置反馈 · 软件急停不能替代硬件安全回路'}}</span><span class="mono">{{ready?'快照 '+hmi.state.sequence+' · '+hmi.state.axes.length+' AXES':'LOCAL DESKTOP · READY'}}</span></footer>
    <div class="toast-stack" aria-live="polite"><div v-for="toast in hmi.toasts" :key="toast.id" class="toast" :class="{'toast-error':!toast.good}"><Check v-if="toast.good" :size="20"/><AlertTriangle v-else :size="20"/><div><strong>{{toast.message}}</strong><small v-if="toast.detail">{{toast.detail}}</small></div><button aria-label="关闭通知" @click="hmi.toasts=hmi.toasts.filter(t=>t.id!==toast.id)"><X :size="16"/></button></div></div>
    <div v-if="settings" class="modal-backdrop" @click.self="settings=false"><section class="modal connection-modal" role="dialog" aria-modal="true" aria-label="连接设置" @keydown.esc="settings=false"><header class="section-heading"><div><p class="eyebrow">DEVICE CONNECTION</p><h2>连接设置</h2></div><button class="button" aria-label="关闭" @click="settings=false"><X :size="18"/></button></header><form @submit.prevent="connect"><div class="segmented"><button type="button" :class="{selected:conn.mode==='serial'}" @click="conn.mode='serial'">串口 Modbus RTU</button><button type="button" :class="{selected:conn.mode==='mock'}" @click="conn.mode='mock'">模拟设备</button></div><div v-if="conn.mode==='serial'" class="form-grid"><label class="full-field">串口<div class="inline"><select v-model="conn.port" required aria-label="串口"><option disabled value="">选择串口</option><option v-for="p in hmi.ports" :key="p.port" :value="p.port">{{p.port}} · {{p.description}}</option></select><button class="button" type="button" aria-label="刷新串口" @click="scanPorts"><RefreshCw :size="16"/></button></div></label><label>波特率<select v-model="conn.baud"><option v-for="n in [9600,19200,38400,57600,115200,230400]" :key="n" :value="n">{{n}}</option></select></label><label>从站地址<input v-model="conn.unit" type="number" min="1" max="247" required/></label><p class="full-field muted small">8 数据位 · 无校验 · 1 停止位。支持 RS485；RS232 需处于 Modbus 模式。</p></div><div v-else class="simulation-description"><span class="badge badge-warn">SIM · 不连接真实设备</span><p>提供八轴运动、回原、点位和软限位的模拟交互。E–H 轴包含原点绑定示例，模拟数据仅在本次连接中保留。</p></div><div v-if="!hmi.native" class="error-text">请通过桌面启动脚本打开程序。</div><footer class="modal-footer"><button v-if="ready" type="button" class="button" :disabled="hmi.pending.disconnect" @click="run('disconnect');settings=false"><Unplug :size="16"/>断开</button><button class="button primary" type="submit" :disabled="hmi.pending.connect||!hmi.native"><Plug :size="16"/>{{hmi.pending.connect?'连接中…':'连接'}}</button></footer></form></section></div>
  </div>
</template>
